import numpy as np

# ---------------------------------------------------------------------------
#    Force models
# ---------------------------------------------------------------------------
def F_ice(F_trac_max, P_ice_max, v):
    """Force generated by the Internal Combustion Engine.
    Traction-limited at low speed, power-limited at high speed."""
    return np.minimum(F_trac_max, P_ice_max / np.maximum(v, 1.0))

def F_MGUK(P_mguk_max, u_row, v_col):
    """Force generated by the Motor Generator Unit -- Kinetic.

    u > 0 : deploy  (motor, adds drive force)
    u < 0 : harvest (generator loaded by the ICE, subtracts drive force)
    Works unchanged for either sign because the force is u * P / v."""
    return u_row * P_mguk_max / v_col

def F_drag(rho_air, CdA, v, drag_mult):
    """Opposing force generated by drag"""
    return 0.5 * rho_air * CdA * drag_mult * v**2

def F_rolling(Crr, m, g):
    """ Opposing generated by rolling friction. Constant."""
    return Crr * m * g

# ---------------------------------------------------------------------------
#    Braking regen (state dependent) & Drag Multiplier dynamics
# ---------------------------------------------------------------------------
def braking_regen(m, P_mguk_max, v_free, v_ceiling, dt):
    """Shaft-side energy the MGU-K can recover over one segment in which the
    car has to brake.

    v_free    : speed at the next node if the car were left alone (ICE only,
                MGU-K neutral) -- shape follows the DP state grid.
    v_ceiling : v_max at the next node (QSS ceiling).
    dt        : time spent in the segment.

    The car must brake exactly when v_free > v_ceiling. The kinetic energy
    that has to be shed is 0.5*m*(v_free^2 - v_ceiling^2); the MGU-K recovers
    as much of it as its power limit allows over the segment. Because it is
    evaluated from the actual state (not from the ceiling profile), a car
    that arrives slower than the ceiling harvests less, and a car that
    arrives faster harvests more (up to the power cap).

    Returns (E_regen, must_brake). Multiply E_regen by the efficiency
    exactly once to get the energy stored in the battery.
    """
    must_brake = v_free > v_ceiling
    e_shed = 0.5 * m * (v_free**2 - v_ceiling**2)
    e_regen = np.where(must_brake, np.minimum(P_mguk_max * dt, e_shed), 0.0)
    return e_regen, must_brake

def drag_multiplier(kappa, kappa_thresh=1.0 / 300.0):
    """Straights (low curvature) run a lower-drag / DRS-like aero setting."""
    return np.where(np.abs(kappa) < kappa_thresh, 0.80, 1.00)
